function criticalCables(n: number, cables: number[][]): number[][] {
  const adj: [number, number][][] = Array.from({ length: n }, () => []);
  cables.forEach(([a, b], i) => { adj[a].push([b, i]); adj[b].push([a, i]); });
  const out: number[][] = [];
  cables.forEach(([a, b], cut) => {
    const seen = new Array<boolean>(n).fill(false);
    const stack = [a];
    seen[a] = true;
    while (stack.length) {
      const u = stack.pop()!;
      for (const [v, id] of adj[u]) {
        if (id !== cut && !seen[v]) { seen[v] = true; stack.push(v); }
      }
    }
    if (!seen[b]) out.push([a, b]);
  });
  return out;
}

