function criticalCables(n: number, cables: number[][]): number[][] {
  const adj: [number, number][][] = Array.from({ length: n }, () => []);
  cables.forEach(([a, b], i) => { adj[a].push([b, i]); adj[b].push([a, i]); });
  const disc = new Array<number>(n).fill(-1), low = new Array<number>(n).fill(0);
  const next = new Array<number>(n).fill(0), inEdge = new Array<number>(n).fill(-1);
  const out: number[][] = [];
  let time = 0;
  for (let s = 0; s < n; s++) {
    if (disc[s] !== -1) continue;
    disc[s] = low[s] = time++;
    const stack = [s];
    while (stack.length) {
      const u = stack[stack.length - 1];
      if (next[u] < adj[u].length) {
        const [v, id] = adj[u][next[u]++];
        if (id === inEdge[u]) continue; // the cable we arrived by
        if (disc[v] === -1) {
          disc[v] = low[v] = time++;
          inEdge[v] = id;
          stack.push(v);
        } else low[u] = Math.min(low[u], disc[v]);
      } else {
        stack.pop();
        if (stack.length) {
          const p = stack[stack.length - 1];
          low[p] = Math.min(low[p], low[u]);
          if (low[u] > disc[p]) out.push([p, u]);
        }
      }
    }
  }
  return out;
}

